// Shared domain types for Escape from Red Hat.
// Engine (authoritative simulation), server (orchestrator + transport), web (renderer + trace) and eval all use these.

export const ACTOR_IDS = ['alex', 'maya', 'daniel', 'rosa', 'kenji'] as const;
export type ActorId = (typeof ACTOR_IDS)[number];

// Zone, door and pull-station ids come from the current map (generated by `npm run data:map`).
import { ZONE_IDS } from './map-ids.generated.js';
export { ALARM_STATION_IDS, DEFAULT_MAP_ID, DOOR_IDS, ZONE_IDS } from './map-ids.generated.js';
export type ZoneId = (typeof ZONE_IDS)[number];

/** fire = spreading fire (multi-instance); electrical = a disabled electric sliding door (power outage / fried device). */
export type HazardKind = 'fire' | 'electrical';
export type Dir = 'down' | 'left' | 'right' | 'up';

export interface Tile {
  col: number;
  row: number;
}

// ---------------------------------------------------------------------------
// Map (generated by data/maps/build-map.ts from data/maps/<id>.spec.ts + <id>.ascii → data/maps/<id>.json)
// ---------------------------------------------------------------------------

export type TerrainKind = 'wall' | 'floor' | 'outdoor' | 'void';

export interface ZoneDef {
  id: ZoneId;
  label: string;
  /** Human noun phrase for viewer- and planner-facing text: "the Red Hat room", "door A", "outside". */
  name: string;
  /** Human locative phrase: "in the Red Hat room", "at door A", "outside". */
  at: string;
  /**
   * What the zone is, which drives the rules: room/corridor = an earshot room of its own; door/exit = joins the
   * rooms on both sides; outdoor/assembly = "outside" (one earshot area, no going back in); exit/outdoor/assembly
   * never burn.
   */
  kind: 'room' | 'corridor' | 'door' | 'exit' | 'outdoor' | 'assembly';
  /** Presenter may drop hazards with any footprint tile in this zone. */
  hazardPlaceable: boolean;
  /** Representative tile used as a move/plan_route target for this zone. */
  anchor: Tile;
}

export interface SpawnSpot extends Tile {
  dir: Dir;
  pose: 'sit' | 'stand';
}

export interface PlacedFurnitureDef {
  uid: string;
  /** Pixel Agents catalog type id, e.g. "DESK_FRONT" or "SOFA_SIDE:left". */
  type: string;
  col: number;
  row: number;
  /** Tiles this item blocks for navigation (engine truth). */
  blocks: Tile[];
}

export type DecorKind =
  | 'sign_redhat'
  | 'sign_nvidia'
  | 'sign_nvidia_logo'
  | 'sign_welcome'
  | 'warden_sign'
  | 'exit_sign'
  | 'evac_plan'
  | 'checkin_flag'
  | 'bus_stop_sign'
  /** Ground markings over an area of `w`×`h` tiles (drawn under everything else). */
  | 'crosswalk'
  | 'lane_line'
  | 'curb';
export interface DecorDef extends Tile {
  kind: DecorKind;
  label?: string;
  /** Area decor size in tiles (default 1). */
  w?: number;
  h?: number;
}

/** Pixel Agents color adjustment (see vendor components/ui/types.ts). */
export interface ColorValue {
  h: number;
  s: number;
  b: number;
  c: number;
  colorize?: boolean;
}

/** Pixel Agents OfficeLayout v1 subset consumed by the renderer. */
export interface PixelLayout {
  version: 1;
  cols: number;
  rows: number;
  tiles: number[];
  furniture: { uid: string; type: string; col: number; row: number; color?: ColorValue }[];
  tileColors: (ColorValue | null)[];
}

/** Electric sliding door (interior only — exit doors are fail-safe/manual and never electrical). */
export interface DoorComponent {
  id: string;
  kind: 'sliding_door';
  label: string;
  /** Human name with its article where it reads naturally: "door A", "the south door". */
  name: string;
  zone: ZoneId;
  tiles: Tile[];
  /** 'horizontal' = door spans columns (in a horizontal wall); 'vertical' = spans rows. */
  orientation: 'horizontal' | 'vertical';
}

/** Manual fire-alarm pull station: mounted on `wall`, operated from the adjacent `stand` tile. */
export interface AlarmStation {
  id: string;
  label: string;
  /** Human name: "the hallway fire alarm". */
  name: string;
  zone: ZoneId;
  wall: Tile;
  stand: Tile;
}

export interface MapData {
  id: string;
  version: number;
  cols: number;
  rows: number;
  tileSize: number;
  /** Row-major arrays, index = row * cols + col. */
  terrain: TerrainKind[];
  zone: (ZoneId | null)[];
  walkable: boolean[];
  /** Wheelchair clearance: walkable and inside some fully walkable 2×2 block. */
  accessible: boolean[];
  /** Floor tiles visually covered by the wall sprite south of them (¾ view). Walkable but costly. */
  occluded: boolean[];
  zones: ZoneDef[];
  zoneEdges: [ZoneId, ZoneId][];
  exits: { id: ZoneId; tiles: Tile[] }[];
  assembly: { tiles: Tile[]; checkInPoint: Tile };
  spawnSpots: Record<ActorId, SpawnSpot[]>;
  activitySpots: Record<ActorId, Tile[]>;
  furniture: PlacedFurnitureDef[];
  decor: DecorDef[];
  /** Electric sliding doors that the Electrical-failure threat can disable. */
  components: DoorComponent[];
  /** Fire-alarm pull stations. */
  alarms: AlarmStation[];
  layout: PixelLayout;
  hash: string;
}

// ---------------------------------------------------------------------------
// Scenario dataset (data/scenarios/*.jsonl)
// ---------------------------------------------------------------------------

export type EventTrigger =
  | { type: 'at_time'; simTime: number }
  | { type: 'actor_enters_zone'; actor: ActorId | 'any'; zone: ZoneId }
  | { type: 'manual' };

export interface ScheduledEvent {
  id: string;
  trigger: EventTrigger;
  action: { type: 'place_hazard'; kind: HazardKind; col: number; row: number };
}

export type CaseFamily = 'hero' | 'fire_only' | 'multi_fire' | 'fire_then_door' | 'independent' | 'trapped';

export interface ScenarioCase {
  caseId: string;
  split: 'demo' | 'dev' | 'test';
  family: CaseFamily;
  seed: number;
  mapId: string;
  spawns: Record<ActorId, SpawnSpot>;
  danielPreference: 'buddy' | 'independent';
  /** Scheduled presenter actions. Live UI ignores 'manual' events (the presenter places by hand). */
  events: ScheduledEvent[];
  /** solvable = at placement time every person had a real route to assembly; expectLosses = trapped by design. */
  labels: { solvable: boolean; primaryRouteBlocked: boolean; expectLosses?: boolean; notes?: string };
}

// ---------------------------------------------------------------------------
// Runtime snapshot (engine → server → web, 10 Hz)
// ---------------------------------------------------------------------------

export type Anim = 'idle' | 'walk' | 'sit' | 'type';
export type ActorStatus =
  | 'working'
  | 'idle'
  | 'alerted'
  | 'moving'
  | 'waiting'
  | 'escorting'
  | 'escorted'
  | 'checked_in'
  | 'lost';

export interface ActorSnapshot {
  id: ActorId;
  name: string;
  role: string;
  /** Current tile. */
  col: number;
  row: number;
  /** Continuous position in tile units (col + fraction) for interpolation. Tile centre = integer. */
  x: number;
  y: number;
  dir: Dir;
  anim: Anim;
  zone: ZoneId | null;
  status: ActorStatus;
  alerted: boolean;
  checkedIn: boolean;
  escort: { role: 'leader' | 'follower'; partner: ActorId } | null;
  task: { kind: 'move' | 'ambient'; destination: string; actionId?: string; tilesRemaining: number } | null;
  knows: string[];
  usesWheelchair: boolean;
  /** Caught by the fire: no longer acts; the renderer plays the disintegration effect. */
  lost: boolean;
  lostAtSimTime?: number;
}

export interface HazardSnapshot {
  id: string;
  kind: HazardKind;
  /** Placement anchor: fire seed top-left, or the disabled door's first tile. */
  col: number;
  row: number;
  /** Fire: currently burning cells. Electrical: the disabled door's tiles. */
  cells: Tile[];
  /** Fire only: burnt-out cells (impassable debris, no longer spreading). */
  charred: Tile[];
  /** Everything impassable because of this hazard (cells ∪ charred). */
  noGo: Tile[];
  /** Electrical: the disabled DoorComponent id. */
  componentId?: string;
  placedAtSimTime: number;
}

export type Phase = 'idle' | 'incident' | 'evacuating' | 'accounting' | 'ended';

/** success = everyone alive, checked in, roster verified; partial = someone lost, all survivors accounted for;
 *  failed = everyone lost; incomplete/unresolved = safety stop (decision cap / stall), never a time limit. */
export type OutcomeStatus = 'success' | 'partial' | 'failed' | 'incomplete' | 'unresolved' | 'aborted';
export interface EpisodeOutcome {
  status: OutcomeStatus;
  reason: string;
  simTime: number;
}

export interface Snapshot {
  episodeId: string;
  caseId: string;
  seed: number;
  tick: number;
  simTime: number;
  phase: Phase;
  paused: boolean;
  mode: 'live' | 'replay';
  actors: ActorSnapshot[];
  hazards: HazardSnapshot[];
  roster: { checkedIn: ActorId[]; verified: boolean; lost: ActorId[] };
  assistance: { required: boolean; requested: boolean; accepted: boolean; fulfilled: boolean };
  alarm: { active: boolean; atSimTime?: number; by?: ActorId; stationId?: string };
  decisions: { used: number; max: number; inFlight: boolean };
  outcome: EpisodeOutcome | null;
}

// ---------------------------------------------------------------------------
// Tool calls and results
// ---------------------------------------------------------------------------

export const TOOL_NAMES = [
  'observe',
  'consult_plan',
  'notify',
  'plan_route',
  'move',
  'request_assistance',
  'assist',
  'check_in',
  'verify_roster',
  'pull_alarm',
] as const;
export type ToolName = (typeof TOOL_NAMES)[number];

/** Provider-agnostic tool call after normalisation. */
export interface NormalizedToolCall {
  /** Provider tool_call id (or synthesized). Used for idempotency. */
  id: string;
  name: string;
  arguments: Record<string, unknown>;
  rawArguments?: string;
}

export const ERROR_CODES = [
  'INVALID_ARGUMENT',
  'UNKNOWN_TOOL',
  'UNKNOWN_ACTOR',
  'UNKNOWN_EVIDENCE',
  'ROUTE_UNAVAILABLE',
  'STALE_STATE',
  'ACTOR_BUSY',
  'OUT_OF_RANGE',
  'ASSISTANCE_NOT_ACCEPTED',
  'NOT_AUTHORIZED',
  'EPISODE_OVER',
] as const;
export type ErrorCode = (typeof ERROR_CODES)[number];

export interface ToolError {
  code: ErrorCode;
  message: string;
  details?: Record<string, unknown>;
  hint?: string;
}

export type ToolResult =
  | {
      ok: true;
      actionId: string;
      /** 'started' = a long-running task (move) was accepted; completion arrives as a later event. */
      status: 'completed' | 'started';
      data: Record<string, unknown>;
      evidenceIds?: string[];
    }
  | { ok: false; actionId: string; error: ToolError };

// ---------------------------------------------------------------------------
// Engine event log (append-only)
// ---------------------------------------------------------------------------

export type WorldEventType =
  | 'episode_started'
  | 'hazard_placed'
  | 'fire_spread'
  | 'cell_charred'
  | 'door_disabled'
  | 'alarm_activated'
  | 'actor_lost'
  /** Engine "human instinct" (NOT a model decision): data.kind = 'shout' | 'flee' | 'alarm'. */
  | 'instinct'
  | 'observation'
  | 'message_delivered'
  | 'tool_executed'
  | 'tool_rejected'
  | 'decision_note'
  | 'move_started'
  | 'move_completed'
  | 'move_interrupted'
  | 'assistance_requested'
  | 'escort_started'
  | 'assistance_fulfilled'
  | 'checked_in'
  | 'roster_verified'
  | 'phase_changed'
  | 'ambient_line'
  | 'episode_ended';

export interface WorldEvent {
  seq: number;
  tick: number;
  simTime: number;
  type: WorldEventType;
  actor?: ActorId;
  /** Present on events caused by a tool action. */
  actionId?: string;
  decisionId?: string;
  data: Record<string, unknown>;
  evidenceIds?: string[];
  ruleIds?: string[];
}

// ---------------------------------------------------------------------------
// Planner view: what Nemotron sees (never includes unobserved hazard truth)
// ---------------------------------------------------------------------------

export interface PlannerView {
  sim_time: number;
  phase: Phase;
  decisions_remaining: number;
  actors: {
    id: ActorId;
    name: string;
    role: string;
    zone: ZoneId | null;
    tile: [number, number];
    status: ActorStatus;
    alerted: boolean;
    checked_in: boolean;
    busy: string | null;
    knows_evidence: string[];
    escort: string | null;
    uses_wheelchair: boolean;
    lost: boolean;
  }[];
  /** Compact: never per-tile lists, and only what the people involved have actually seen or been told. */
  evidence: {
    id: string;
    kind: HazardKind;
    /** Zone where it was first observed. */
    zone: ZoneId | null;
    /** Zones containing known affected cells. */
    zones: ZoneId[];
    /** Fire: burning/charred cells known to anyone. Electrical: the door's tiles. */
    cells_known: number;
    /** [minCol, minRow, maxCol, maxRow] of known cells. */
    bbox: [number, number, number, number] | null;
    /** Electrical: the disabled door component. */
    component?: string;
    /** Fire only: fires keep spreading. */
    spreading?: boolean;
    observed_by: ActorId;
    at: number;
    known_by: ActorId[];
  }[];
  alarm: {
    active: boolean;
    at?: number;
    by?: ActorId;
    stations: { id: string; zone: ZoneId; stand: [number, number] }[];
  };
  messages: { from: ActorId; to: string; topic: string; evidence_ids: string[]; message: string; at: number }[];
  assistance: {
    person: ActorId;
    preference: 'buddy' | 'independent';
    buddy: ActorId;
    requested: boolean;
    accepted: boolean;
    fulfilled: boolean;
  };
  roster: { checked_in: ActorId[]; verified: boolean; lost: ActorId[] };
  routes: { route_id: string; actor: ActorId; destination: string; zones: ZoneId[]; knowledge_revision: number }[];
  recent_actions: {
    decision: string;
    actor?: string;
    tool?: string;
    args?: Record<string, unknown>;
    ok: boolean;
    summary: string;
    error_code?: string;
    hint?: string;
  }[];
  new_since_last_decision: string[];
}

/**
 * Per-agent mode: what ONE person knows right now — their own sightings, what they were told, who is in the same room,
 * the siren. Never other people's private knowledge (unlike PlannerView, which merges the whole team's knowledge).
 */
export interface AgentView {
  sim_time: number;
  me: {
    id: ActorId;
    name: string;
    role: string;
    zone: ZoneId | null;
    place: string;
    tile: [number, number];
    status: ActorStatus;
    alerted: boolean;
    checked_in: boolean;
    /** Outside the building (sidewalk, plaza, assembly area). */
    outside: boolean;
    /** What I'm doing right now, if anything ("moving to assembly, 12 tiles left"). */
    doing: string | null;
    uses_wheelchair: boolean;
    escort: string | null;
  };
  /** People in the same room as me (in earshot / sight). */
  with_me: { id: ActorId; name: string; status: ActorStatus; alerted: boolean; checked_in: boolean; doing: string | null }[];
  /** Everyone else: where I last know them to be, or "not in sight". */
  others: { id: ActorId; name: string; where: string }[];
  /** Hazards I have seen or been told about, with only the cells I know. */
  hazards: {
    id: string;
    kind: HazardKind;
    what: string;
    zones: ZoneId[];
    places: string[];
    cells_known: number;
    bbox: [number, number, number, number] | null;
    component?: string;
    spreading?: boolean;
  }[];
  alarm: { sounding: boolean; station: { id: string; zone: ZoneId; stand: [number, number] }[] };
  /** Messages spoken to me. */
  heard: { from: ActorId; topic: string; evidence_ids: string[]; message: string; at: number }[];
  /** Buddy/assistance arrangements involving me. */
  assistance: { requested_by_me: ActorId | null; requested_of_me: ActorId[]; escorting: ActorId | null; escorted_by: ActorId | null };
  /** Only visible at the assembly point: who has checked in there. */
  roster: { checked_in: ActorId[]; verified: boolean } | null;
  my_routes: { route_id: string; destination: string; zones: ZoneId[]; knowledge_revision: number }[];
  my_recent_actions: { tool?: string; args?: Record<string, unknown>; ok: boolean; summary: string; error_code?: string; hint?: string }[];
  /** What changed for me since my last decision. */
  new_for_me: string[];
}

// ---------------------------------------------------------------------------
// Trace (server → web): every real proposal, result and engine event
// ---------------------------------------------------------------------------

export type TraceStatus =
  | 'proposed'
  | 'held'
  | 'accepted'
  | 'running'
  | 'completed'
  | 'failed'
  | 'rejected'
  | 'malformed'
  | 'provider_error'
  | 'discarded_stale'
  | 'ignored'
  | 'info';

export interface ProviderInfo {
  id: string;
  label: string;
  model: string;
  endpointKind: 'self-hosted-vllm' | 'hosted-api' | 'scripted';
  baseUrl?: string;
  healthy: boolean | null;
  healthDetail?: string;
  thinking: boolean;
  /** Reasoning-token cap per decision, when one is sent (vLLM `thinking_token_budget`). */
  thinkingBudget?: number;
  /** 'central' = one planner directs everyone; 'agents' = each person decides for themselves. */
  mode?: 'central' | 'agents';
  p50LatencyMs?: number;
  lastLatencyMs?: number;
}

export interface TraceRow {
  id: string;
  episodeId: string;
  kind: 'decision' | 'engine';
  decisionId?: string;
  actionId?: string;
  eventSeq?: number;
  /** e.g. "Nemotron planner → Maya → notify" or "Engine". */
  origin: string;
  actor?: ActorId;
  tool?: string;
  args?: Record<string, unknown>;
  status: TraceStatus;
  summary: string;
  result?: ToolResult;
  reasonSummary?: string;
  /** Per-agent mode with reasoning on: the model's own thinking for this decision (trimmed). */
  reasoning?: string;
  evidenceIds?: string[];
  simTime: number;
  wallTime: number;
  latencyMs?: number;
  usage?: { promptTokens?: number; completionTokens?: number };
  provider?: { id: string; model: string; endpointKind: ProviderInfo['endpointKind'] };
  parseMode?: 'native' | 'content-fallback';
  recovered?: boolean;
  raw?: { request?: unknown; response?: unknown };
}

// ---------------------------------------------------------------------------
// Results, metrics, debrief
// ---------------------------------------------------------------------------

export interface DebriefLesson {
  id: 'reporting' | 'alarm' | 'routes' | 'assistance' | 'accountability' | 'losses' | 'unresolved';
  title: string;
  text: string;
  ruleIds: string[];
  sources: { label: string; url: string }[];
}

export interface EpisodeMetrics {
  decisions: number;
  toolCalls: number;
  validCalls: number;
  invalidCalls: number;
  invalidByCode: Record<string, number>;
  malformed: number;
  providerErrors: number;
  recoveries: number;
  repeatedInvalid: number;
  simTimeToComplete: number | null;
  simTime: number;
  wallTimeMs: number;
  latencyMsP50: number | null;
  latencyMsP95: number | null;
  promptTokens: number;
  completionTokens: number;
  procedural: {
    hazardReported: boolean;
    reportLatencySimSec: number | null;
    assistanceRequired: boolean;
    assistanceFulfilled: boolean;
    assistWithoutConsentAttempts: number;
    checkedIn: number;
    rosterVerified: boolean;
    prematureVerifyAttempts: number;
    knownHazardMoveAttempts: number;
    routeInterruptions: number;
    replannedAfterInterruption: boolean;
    alarmRaised: boolean;
    alarmLatencySimSec: number | null;
    /** Who raised the alarm: the planner (pull_alarm tool) or a person's instinct on their way past the station. */
    alarmBy: 'planner' | 'instinct' | null;
    /** Times people backed away from nearby fire by instinct. */
    instinctFlees: number;
    /** Survivors who reached the assembly point and checked in. */
    escaped: number;
    lost: number;
  };
}

export interface EpisodeResult {
  episodeId: string;
  caseId: string;
  outcome: EpisodeOutcome;
  metrics: EpisodeMetrics;
  debrief: DebriefLesson[];
  score: { reward: number; success: boolean; checks: Record<string, boolean | number> };
}
